// en.yaml rule en.fixedPhrases def fixedFound
export function fixedFound(
  ctx: DetectContext,
  frame: FrameRef,
  m: RegExpExecArray,
  start: number,
  end: number,
  alternatives: readonly string[],
  recase: boolean,
): RawFinding | null {
  if (hasUserOrCasedWord(ctx, m[0])) return null;
  const typed = ctx.text.slice(start, end);
  const cased = alternatives.map((alt) => (recase ? caseLike(typed, alt) : alt));
  return {
    ruleId: frame.ruleId,
    messageKey: frame.messageKey,
    range: { start, end },
    alternatives: cased,
    ...(cased.length > 1 ? { requiresChoice: true as const } : {}),
    context: {
      start: Math.max(0, m.index - 32),
      end: Math.min(ctx.text.length, m.index + m[0].length + 16),
    },
  };
}

// en.yaml rule en.fixedPhrases def fixedTarget
export function fixedTarget(
  ctx: DetectContext,
  frame: FrameRef,
  m: RegExpExecArray,
  alternatives: readonly string[],
) {
  const range = group(m, "target");
  return fixedFound(ctx, frame, m, range[0], range[1], alternatives, true);
}

// en.yaml rule en.fixedPhrases def fixedSwap
export function fixedSwap(
  ctx: DetectContext,
  frame: FrameRef,
  m: RegExpExecArray,
  replacement: string | null,
  recase: boolean,
) {
  const range = group(m, "target");
  return replacement ? fixedFound(ctx, frame, m, range[0], range[1], [replacement], recase) : null;
}

// en.yaml rule en.fixedPhrases def fixedTyped
export function fixedTyped(ctx: DetectContext, m: RegExpExecArray) {
  const range = group(m, "target");
  return ctx.text.slice(range[0], range[1]);
}

// en.yaml rule en.fixedPhrases def fixedClauseStart
export function fixedClauseStart(ctx: DetectContext, index: number) {
  return /(?:^|[.!?;:\n])[ \t\u00a0"“'‘(]*$/.test(enBefore(ctx, index, 96));
}

// en.yaml rule en.fixedPhrases def FIXED_CLOSED_CLASS
export const FIXED_CLOSED_CLASS =
  /^(?:if|in|on|at|to|for|with|by|of|off|out|up|down|over|than|and|or|but|so|as|when|because|since|after|before|until|now|then|again|lately|here|there|yet|still|too|very|it|this|that)$/i;

// en.yaml rule en.fixedPhrases def fixedNounLike
export function fixedNounLike(word: string, unknownLong: boolean) {
  if (!(word && !FIXED_CLOSED_CLASS.test(word))) return false;
  const info = englishWordInfo(word.toLowerCase());
  return info ? info.noun || info.plural : word.length > 6 && (unknownLong || /s$/i.test(word));
}

// en.yaml rule en.fixedPhrases def FIXED_NOUN_DOSE_NEXT
export const FIXED_NOUN_DOSE_NEXT =
  /^(?:of|is|was|are|were|has|had|have|should|would|will|can|could|may|might|must|per|for|and|or|to|in|on|at|level|levels|amount|size|range|form)$/i;

// en.yaml rule en.fixedPhrases def FIXED_PRONOUN_NEXT
export const FIXED_PRONOUN_NEXT = /^(?:it|he|she|this|that|they|we|you|i)$/i;

// en.yaml rule en.fixedPhrases def FIXED_WORSE
export const FIXED_WORSE = new WeakSet<RawFinding>();

// en.yaml rule en.fixedPhrases def FIXED_HELD
export const FIXED_HELD = new WeakSet<RawFinding>();

// en.yaml rule en.fixedPhrases def fixedWorse
export function fixedWorse(ctx: DetectContext, frame: FrameRef, m: RegExpExecArray, word: string) {
  const range = group(m, "target");
  const result = fixedFound(ctx, frame, m, range[0], range[1], [word], true);
  return remember(
    FIXED_WORSE,
    result ??
      remember(FIXED_HELD, {
        ruleId: frame.ruleId,
        messageKey: frame.messageKey,
        range: { start: range[0], end: range[1] },
        alternatives: [],
      }),
  );
}

// en.yaml rule en.fixedPhrases def FIXED_SITUATION
export const FIXED_SITUATION =
  /(?:\bmuch|\b(?:it|this|that|which)(?:['’]s|[ \t\u00a0]+(?:is|was|were|be|been|will[ \t\u00a0]+be))[ \t\u00a0]+(?:(?:a|such[ \t\u00a0]+a|quite[ \t\u00a0]+a|a[ \t\u00a0]+real|a[ \t\u00a0]+total|a[ \t\u00a0]+complete)[ \t\u00a0]+)?)[ \t\u00a0]*$/i;

// en.yaml rule en.fixedPhrases def FIXED_NONSENSE_CUE
export const FIXED_NONSENSE_CUE =
  /(?:\b(?:complete|total|utter|absolute|pure|such|dogs|is|was|its|thats|what|bloody|just)|['’]s)[ \t\u00a0]+$/i;

// en.yaml rule en.fixedPhrases def FIXED_TO_FAR_NEXT
export const FIXED_TO_FAR_NEXT =
  /^(?:with|for|on|in|this|and|but|when|because|like|away|off|out|flung)$/i;

// en.yaml rule en.fixedPhrases def FIXED_SETTING_VERB
export const FIXED_SETTING_VERB =
  /\b(?:set|sets|setting|change|changes|changed|changing|switch|switched|resize|resized|scale|scaled|convert|converted|from|increase|increased|reduce|reduced|default|defaults|move|moved|grow|grows|grew|shrink|shrank)\b[^.!?;:\n]*$/i;

// en.yaml rule en.confusedWords def CONF_BOUNDARY
export const CONF_BOUNDARY = /^[.!?;:"“”([…\uFFFC*+#>|-]$/;

// en.yaml rule en.confusedWords def confOpens
export function confOpens(t: EnBlockToken | undefined) {
  return !t || CONF_BOUNDARY.test(t.text);
}

// en.yaml rule en.confusedWords def confEnds
export function confEnds(t: EnBlockToken | undefined) {
  return !t || /^[.!?;:,)"”…]$/.test(t.text);
}

// en.yaml rule en.confusedWords def confCount
export function confCount(
  b: EnBlockToken[],
  i: number,
  max: number,
  test: typeof confAdverbToken,
): number {
  return i < max && test(b[i]) ? confCount(b, i + 1, max, test) : i;
}

// en.yaml rule en.confusedWords def confIsAdverb
export function confIsAdverb(w: string) {
  return CONF_ADVERB.has(w) || (/^[a-z]{3,}ly$/.test(w) && confLyAdverb(w));
}

// en.yaml rule en.confusedWords def confLyAdverb
export function confLyAdverb(w: string) {
  const info = englishWordInfo(w);
  return !info || info.adverb || (!info.noun && !info.verbs.length);
}

// en.yaml rule en.confusedWords def confAdverbToken
export function confAdverbToken(t: EnBlockToken | undefined) {
  return enIsBlockWord(t) && confIsAdverb(t.w);
}

// en.yaml rule en.confusedWords def confPlainAdjective
export function confPlainAdjective(w: string) {
  if (!(!CONF_ADVERBISH.has(w) && !CONF_DETERMINER.has(w) && !CONF_FUNCTION.has(w))) return false;
  const info = englishWordInfo(w);
  return !!info && info.adjective && !info.adverb && !info.verbs.length && !/ly$/.test(w);
}

// en.yaml rule en.confusedWords def confHasVerb
export function confHasVerb(w: string) {
  return !!englishWordInfo(w)?.verbs.length;
}

// en.yaml rule en.confusedWords def confHit
export function confHit(t: EnBlockToken, alts: string[]): EnBlockHit {
  return { start: t.start, end: t.end, alts };
}

// en.yaml rule en.confusedWords def confCue
export function confCue(b: EnBlockToken[]): { kind: string; at: number; adverbs: number } | null {
  const i = confCount(b, 0, 3, confAdverbToken);
  const t = b[i];
  return !enIsBlockWord(t)
    ? i > 0 && /^(?:never|always|just)$/.test(b[i - 1].w)
      ? { kind: "subject", at: i - 1, adverbs: i - 1 }
      : null
    : confCueAt(b, i, t);
}

// en.yaml rule en.confusedWords def confCueAt
export function confCueAt(
  b: EnBlockToken[],
  i: number,
  t: EnBlockToken,
): { kind: string; at: number; adverbs: number } | null {
  const w = t.w;
  return CONF_SUBJECT.has(w)
    ? confObjectYou(b, i, w)
      ? null
      : { kind: "subject", at: i, adverbs: i }
    : CONF_THIRD.has(w)
      ? { kind: "third", at: i, adverbs: i }
      : CONF_HAVE.has(w)
        ? { kind: "have", at: i, adverbs: i }
        : CONF_MODAL.has(w) || /^[a-z]+'(?:d|ll)$/.test(w)
          ? confModalNoun(b, i, w)
            ? null
            : { kind: "modal", at: i, adverbs: i }
          : w === "to"
            ? { kind: "to", at: i, adverbs: i }
            : w === "please"
              ? { kind: "subject", at: i, adverbs: i }
              : i > 0 &&
                  /^(?:never|always|just)$/.test(b[i - 1].w) &&
                  (confOpens(t) || /^(?:and|but|so|then)$/.test(w))
                ? { kind: "subject", at: i - 1, adverbs: i - 1 }
                : confInvertedQuestion(b, i, w)
                  ? { kind: "modal", at: 2, adverbs: 0 }
                  : CONF_INDEFINITE.has(w) || (w === "body" && b[i + 1]?.w === "every")
                    ? { kind: "indefinite", at: i, adverbs: i }
                    : w === "who"
                      ? { kind: "who", at: i, adverbs: i }
                      : null;
}

// en.yaml rule en.confusedWords def confObjectYou
export function confObjectYou(b: EnBlockToken[], i: number, w: string) {
  const p = b[i + 1];
  if (!(w === "you" && enIsBlockWord(p))) return false;
  return (
    (!CONF_MODAL.has(p.w) &&
      !CONF_CONJUNCTION.has(p.w) &&
      !confIsAdverb(p.w) &&
      confHasVerb(p.w)) ||
    /^(?:to|for|with|of|thank)$/.test(p.w)
  );
}

// en.yaml rule en.confusedWords def confModalNoun
export function confModalNoun(b: EnBlockToken[], i: number, w: string) {
  return (
    (CONF_NOUN_MODAL.has(w) &&
      enIsBlockWord(b[i + 1]) &&
      /^(?:a|an|the|my|your|his|our|their|its|no|every)$/.test(b[i + 1].w)) ||
    (/^(?:do|does|did)$/.test(w) && i === 0) ||
    (confOpens(b[i + 1]) && !/n't$|^cannot$/.test(w))
  );
}

// en.yaml rule en.confusedWords def confInvertedQuestion
export function confInvertedQuestion(b: EnBlockToken[], i: number, w: string) {
  return (
    i === 0 &&
    !CONF_FUNCTION.has(w) &&
    !englishWordInfo(w)?.adjective &&
    enIsBlockWord(b[1]) &&
    /^(?:the|this|that|my|your|our|their|his|its)$/.test(b[1].w) &&
    enIsBlockWord(b[2]) &&
    CONF_MODAL.has(b[2].w) &&
    ((enIsBlockWord(b[3]) && /^(?:how|why|when|where|what|which)$/.test(b[3].w)) ||
      (confOpens(b[3]) && !/^(?:do|does|did)$/.test(b[2].w)))
  );
}

// en.yaml rule en.confusedWords def confInfinitiveTo
export function confInfinitiveTo(
  b: EnBlockToken[],
  c: { kind: string; at: number; adverbs: number },
  next: EnBlockToken | undefined,
) {
  const head = b[c.at + 1];
  if (!(enIsBlockWord(head) && !CONF_PREPOSITION_HEAD.has(head.w))) return false;
  return (
    c.adverbs > 0 ||
    CONF_TO_HEAD.has(head.w) ||
    (enIsBlockWord(next) && CONF_OBJECT_START.has(next.w))
  );
}

// en.yaml rule en.confusedWords def confNounForVerb
export function confNounForVerb(
  ctx: DetectContext,
  t: EnBlockToken,
  b: EnBlockToken[],
  a: EnBlockToken[],
): EnBlockHit | null {
  const c = confCue(b);
  if (!(c && c.kind !== "have" && c.kind !== "third")) return null;
  if (c.kind === "indefinite" && t.w !== "thing") return null;
  if (c.kind === "who" && c.adverbs === 0) return null;
  if (c.kind === "to" && (t.w === "response" || !confInfinitiveTo(b, c, a[0]))) return null;
  if (t.w === "intent" && a[0]?.w === "on") return null;
  if (b[c.at]?.text === "i" && a[0]?.w === "," && a[1]?.w === "ii") return null;
  return confHit(t, [CONF_NOUN_FOR_VERB[t.w]]);
}

// en.yaml rule en.confusedWords def confVerbForNoun
export function confVerbForNoun(
  ctx: DetectContext,
  t: EnBlockToken,
  b: EnBlockToken[],
  a: EnBlockToken[],
): EnBlockHit | null {
  if (enIsBlockWord(a[0]) && CONF_OBJECT_START.has(a[0].w)) return null;
  const i = enIsBlockWord(b[0]) && confPlainAdjective(b[0].w) ? 1 : 0;
  const p = b[i];
  const noun =
    (enIsBlockWord(p) && (CONF_DETERMINER.has(p.w) || /^(?:of|for|without)$/.test(p.w))) ||
    (i === 1 &&
      (confOpens(p) ||
        (enIsBlockWord(p) &&
          (confIsAdverb(p.w) ||
            (confHasVerb(p.w) && !CONF_MODAL.has(p.w) && !CONF_SUBJECT.has(p.w))))));
  if (!noun) return null;
  return confHit(t, [CONF_VERB_FOR_NOUN[t.w]]);
}

// en.yaml rule en.confusedWords def confEffect
export function confEffect(
  ctx: DetectContext,
  t: EnBlockToken,
  b: EnBlockToken[],
  a: EnBlockToken[],
): EnBlockHit | null {
  const third = t.w === "effects";
  const next = a[0];
  if (!(
    enIsBlockWord(next) &&
    !/^(?:of|on|in|is|was|are|were|that|for|and|or|to|from|has|have)$/.test(next.w)
  ))
    return null;
  if (a.slice(0, 3).some((x) => CONF_EFFECT_OBJECT.has(x.w)) || next.w === "a" || next.w === "an")
    return null;
  const c = confCue(b);
  return confEffectByCue(b, c, next, third) || confEffectBySubject(b, next, third)
    ? confHit(t, [third ? "affects" : "affect"])
    : null;
}

// en.yaml rule en.confusedWords def confEffectByCue
export function confEffectByCue(
  b: EnBlockToken[],
  c: { kind: string; at: number; adverbs: number } | null,
  next: EnBlockToken,
  third: boolean,
) {
  return (
    !!c &&
    ((third ? c.kind === "third" : c.kind === "modal" || c.kind === "subject") ||
      (!third &&
        c.kind === "to" &&
        confInfinitiveTo(b, c, next) &&
        CONF_OBJECT_START.has(next.w)) ||
      (!third && c.kind === "to" && CONF_TO_HEAD.has(b[c.at + 1]?.w ?? "")))
  );
}

// en.yaml rule en.confusedWords def confEffectBySubject
export function confEffectBySubject(b: EnBlockToken[], next: EnBlockToken, third: boolean) {
  const i = confCount(b, 0, 2, confAdverbNotNot);
  const s = b[i];
  if (!(enIsBlockWord(s) && !CONF_DETERMINER.has(s.w))) return false;
  const info = englishWordInfo(s.w);
  const subject = third
    ? info?.noun && !info.plural
    : info?.plural || (!info && /[^s]s$/.test(s.w));
  if (!(subject && !(i === 0 && !CONF_OBJECT_START.has(next.w)))) return false;
  const j = confCount(b, i + 1, i + 3, confModifier);
  if (enIsBlockWord(b[j]) && /^(?:what|which|whose)$/.test(b[j].w)) return false;
  if (!(
    confOpens(b[j]) ||
    (enIsBlockWord(b[j]) &&
      (CONF_DETERMINER.has(b[j].w) ||
        CONF_CONJUNCTION.has(b[j].w) ||
        /^(?:these|those)$/.test(b[j].w)))
  ))
    return false;
  return true;
}

// en.yaml rule en.confusedWords def confAdverbNotNot
export function confAdverbNotNot(t: EnBlockToken | undefined) {
  return enIsBlockWord(t) && confIsAdverb(t.w) && t.w !== "not";
}

// en.yaml rule en.confusedWords def confModifier
export function confModifier(t: EnBlockToken | undefined) {
  if (!(
    enIsBlockWord(t) &&
    !CONF_FUNCTION.has(t.w) &&
    !CONF_HAVE.has(t.w) &&
    !CONF_MODAL.has(t.w) &&
    !CONF_BE_FINITE.has(t.w)
  ))
    return false;
  const info = englishWordInfo(t.w);
  return (
    !info ||
    info.noun ||
    info.plural ||
    info.adjective ||
    info.verbs.some((v) => v.form === "participle" || v.form === "ing")
  );
}

// en.yaml rule en.confusedWords def confAffect
export function confAffect(
  ctx: DetectContext,
  t: EnBlockToken,
  b: EnBlockToken[],
  a: EnBlockToken[],
): EnBlockHit | null {
  return confAffectNoun(b, a) ? confHit(t, [t.w === "affects" ? "effects" : "effect"]) : null;
}

// en.yaml rule en.confusedWords def confAffectNoun
export function confAffectNoun(b: EnBlockToken[], a: EnBlockToken[]) {
  const next = a[0];
  const i = confCount(b, 0, 3, confAffectModifier);
  return (
    (enIsBlockWord(next) && /^(?:on|upon|of)$/.test(next.w) && a[1]?.w !== "average") ||
    (i > 0 && enIsBlockWord(b[i]) && CONF_HAVE.has(b[i].w)) ||
    (b[0]?.w === "into" &&
      b
        .slice(1, 6)
        .some((x) =>
          /^(?:put|puts|putting|come|comes|came|coming|go|goes|went|going|gone|bring|brings|brought|bringing)$/.test(
            x.w,
          ),
        )) ||
    (b[0]?.w === "in" &&
      enIsBlockWord(b[1]) &&
      /^(?:is|are|was|were|be|been|now|still|already|remain|remains|remained|stay|stays|stayed|currently|fully|come|comes|came)$/.test(
        b[1].w,
      )) ||
    (enIsBlockWord(b[0]) &&
      CONF_COLLOCATION.has(b[0].w) &&
      (!enIsBlockWord(next) || !CONF_OBJECT_START.has(next.w)) &&
      (!enIsBlockWord(next) ||
        /^(?:is|are|was|were|remain|remains|remained|can|could|will|would|may|might|amplified|warms|included|include|includes|across|throughout|than)$/.test(
          next.w,
        ) ||
        confEnds(next)))
  );
}

// en.yaml rule en.confusedWords def confAffectModifier
export function confAffectModifier(t: EnBlockToken | undefined) {
  return (
    enIsBlockWord(t) &&
    (CONF_DETERMINER.has(t.w) ||
      /^(?:little|much|any|some|great|big)$/.test(t.w) ||
      confPlainAdjective(t.w) ||
      !!englishWordInfo(t.w)?.adjective)
  );
}

// en.yaml rule en.confusedWords def confBeAdjective
export function confBeAdjective(
  ctx: DetectContext,
  t: EnBlockToken,
  b: EnBlockToken[],
  a: EnBlockToken[],
): EnBlockHit | null {
  const i = confCount(b, 0, 2, confAdverbToken);
  const be = b[i];
  if (!enIsBlockWord(be)) return null;
  const personal =
    CONF_PERSONAL_BE.has(be.w) ||
    (/^(?:am|is|are|was|were)$/.test(be.w) &&
      enIsBlockWord(b[i + 1]) &&
      /^(?:i|he|she|we|you|they)$/.test(b[i + 1].w));
  if (!personal) return null;
  if (enIsBlockWord(a[0]) && /^(?:is|was|are|were|has|have|had|will|can|free)$/.test(a[0].w))
    return null;
  if (enIsBlockWord(a[0]) && englishWordInfo(a[0].w)?.plural) return null;
  return confHit(t, [CONF_BE_ADJECTIVE[t.w]]);
}

// en.yaml rule en.confusedWords def confSafe
export function confSafe(
  ctx: DetectContext,
  t: EnBlockToken,
  b: EnBlockToken[],
  a: EnBlockToken[],
): EnBlockHit | null {
  const next = a[0];
  if (!(
    enIsBlockWord(next) &&
    !/^(?:to|from|for|and|or|enough|with|in|on|at|than|as|by|if|when|place|mode|side|now|here)$/.test(
      next.w,
    )
  ))
    return null;
  const c = confCue(b);
  if (!(
    c &&
    (c.kind === "modal" ||
      (c.kind === "to" && confInfinitiveTo(b, c, next) && CONF_OBJECT_START.has(next.w)))
  ))
    return null;
  return confHit(t, ["save"]);
}

// en.yaml rule en.confusedWords def confWeight
export function confWeight(
  ctx: DetectContext,
  t: EnBlockToken,
  b: EnBlockToken[],
  a: EnBlockToken[],
): EnBlockHit | null {
  if (!(confEnds(a[0]) && enIsBlockWord(b[0]) && /^(?:i|you|we|they|he|she|it)$/.test(b[0].w)))
    return null;
  if (!(
    enIsBlockWord(b[1]) &&
    /^(?:do|does|did|than|will|would|can|could|should|might|may)$/.test(b[1].w)
  ))
    return null;
  return confHit(t, ["weigh"]);
}

// en.yaml rule en.confusedWords def confBough
export function confBough(
  ctx: DetectContext,
  t: EnBlockToken,
  b: EnBlockToken[],
  a: EnBlockToken[],
): EnBlockHit | null {
  const c = confCue(b);
  if (!(c && /^(?:subject|third|have)$/.test(c.kind) && enIsBlockWord(a[0]))) return null;
  return confHit(t, ["bought"]);
}

// en.yaml rule en.confusedWords def confFell
export function confFell(
  ctx: DetectContext,
  t: EnBlockToken,
  b: EnBlockToken[],
  a: EnBlockToken[],
): EnBlockHit | null {
  const c = confCue(b);
  if (!(c && /^(?:subject|modal|who)$/.test(c.kind))) return null;
  const n = a[0];
  if (!enIsBlockWord(n)) return null;
  if (!confFeel(n, a[1])) return null;
  return confHit(t, ["feel"]);
}

// en.yaml rule en.confusedWords def confFeel
export function confFeel(n: EnBlockToken, n1: EnBlockToken | undefined) {
  return n.w === "like"
    ? !enIsBlockWord(n1) || !/^(?:a|an|the|rain|dominoes|flies|stones?|rocks?)$/.test(n1.w)
    : n.w === "free" || n.w === "that"
      ? true
      : /^(?:i|i'm|i've|i'd|we|you|they|he|she|it's|that's|there's|this)$/.test(n.w)
        ? true
        : n.w === "it"
          ? enIsBlockWord(n1) && hasVerbForm(n1.w, "third", "past")
          : !CONF_FALL_STATE.has(n.w) && confAdjectiveOnly(n.w);
}

// en.yaml rule en.confusedWords def confAdjectiveOnly
export function confAdjectiveOnly(w: string) {
  const info = englishWordInfo(w);
  return !!info && info.adjective && !info.adverb;
}

// en.yaml rule en.confusedWords def confQuiet
export function confQuiet(
  ctx: DetectContext,
  t: EnBlockToken,
  b: EnBlockToken[],
  a: EnBlockToken[],
): EnBlockHit | null {
  const n = a[0];
  if (!enIsBlockWord(n)) return null;
  const info = englishWordInfo(n.w);
  const verbal = info?.verbs.every((v) => v.form === "ing" || v.form === "participle");
  const n1 = a[1];
  return (info &&
    info.adjective &&
    !info.noun &&
    verbal &&
    !CONF_ADVERBISH.has(n.w) &&
    (confEnds(n1) || /^(?:that|to|and|but|for|in|at)$/.test(n1.w))) ||
    (/n't$|^(?:not|never)$/.test(b[0]?.w ?? "") &&
      hasVerbForm(n.w, "base") &&
      !CONF_OBJECT_PRONOUN.has(n.w) &&
      !/^(?:down|up|people|things|everyone|everybody|them|us|the|a|an)$/.test(n.w) &&
      !englishWordInfo(n.w)?.plural)
    ? confHit(t, ["quite"])
    : null;
}

// en.yaml rule en.confusedWords def confFind
export function confFind(
  ctx: DetectContext,
  t: EnBlockToken,
  b: EnBlockToken[],
  a: EnBlockToken[],
): EnBlockHit | null {
  const i =
    enIsBlockWord(b[0]) && /^(?:all|totally|perfectly|just|really|also)$/.test(b[0].w) ? 1 : 0;
  const be = b[i];
  if (!(
    enIsBlockWord(be) &&
    /^(?:am|is|are|was|were|be|been|i'm|im|it's|that's|we're|you're|they're|he's|she's)$/.test(be.w)
  ))
    return null;
  const n = a[0];
  if (!(
    confEnds(n) ||
    /^(?:for|with|but|and|now|not|by|here|there|too|as|so|though|otherwise|either|without)$/.test(
      n.w,
    )
  ))
    return null;
  return confHit(t, ["fine"]);
}

// en.yaml rule en.confusedWords def confHop
export function confHop(
  ctx: DetectContext,
  t: EnBlockToken,
  b: EnBlockToken[],
  a: EnBlockToken[],
): EnBlockHit | null {
  return t.w === "hop" || t.w === "hops" ? confHopeVerb(t, b, a) : confHopVerb(t, a);
}

// en.yaml rule en.confusedWords def confHopeVerb
export function confHopeVerb(
  t: EnBlockToken,
  b: EnBlockToken[],
  a: EnBlockToken[],
): EnBlockHit | null {
  if (!(enIsBlockWord(b[0]) && /^(?:i|we|they|you)$/.test(b[0].w))) return null;
  if (!(
    enIsBlockWord(a[0]) &&
    /^(?:we|you|i|they|he|she|that|this|everything|everyone|so|not|it'll|it's|you're|we're|they're)$/.test(
      a[0].w,
    )
  ))
    return null;
  return confHit(t, [t.w === "hop" ? "hope" : "hopes"]);
}

// en.yaml rule en.confusedWords def confHopVerb
export function confHopVerb(t: EnBlockToken, a: EnBlockToken[]): EnBlockHit | null {
  if (!(
    a[0]?.w === "on" &&
    enIsBlockWord(a[1]) &&
    /^(?:a|an|the|my|our|your|their|his|her)$/.test(a[1].w)
  ))
    return null;
  if (!(enIsBlockWord(a[2]) && CONF_BOARDED.has(a[2].w))) return null;
  if (
    enIsBlockWord(a[3]) &&
    /^(?:we|you|i|they|he|she|it|there|there's|it's|everyone|someone|this|that)$/.test(a[3].w)
  )
    return null;
  const alt = CONF_HOP[t.w];
  if (!alt) return null;
  return confHit(t, [alt]);
}

// en.yaml rule en.confusedWords def confCant
export function confCant(
  ctx: DetectContext,
  t: EnBlockToken,
  b: EnBlockToken[],
  a: EnBlockToken[],
): EnBlockHit | null {
  if (!(t.text !== "CANT" && enIsBlockWord(a[0]))) return null;
  const n = a[0].w;
  const inverted = confOpens(b[0]) && /^(?:you|we|i|they|he|she|it)$/.test(n);
  const v = confIsAdverb(n) && enIsBlockWord(a[1]) ? a[1].w : n;
  return inverted || confCantVerb(b, v)
    ? { ...confHit(t, ["can't"]), key: "review_msg_contraction" }
    : null;
}

// en.yaml rule en.confusedWords def confCantVerb
export function confCantVerb(b: EnBlockToken[], v: string) {
  if (!(v !== "cant")) return false;
  const info = englishWordInfo(v);
  if (!(info?.verbs.some((x) => x.form === "base") && !info.plural && !CONF_DETERMINER.has(v)))
    return false;
  return !(enIsBlockWord(b[0]) && (CONF_DETERMINER.has(b[0].w) || confPlainAdjective(b[0].w)));
}

// en.yaml rule en.confusedWords def confRogue
export function confRogue(
  ctx: DetectContext,
  t: EnBlockToken,
  b: EnBlockToken[],
  a: EnBlockToken[],
): EnBlockHit | null {
  return b[0]?.w === "lip" || a[0]?.w === "lipstick" ? confHit(t, ["rouge"]) : null;
}

// en.yaml rule en.confusedWords def confRoller
export function confRoller(
  ctx: DetectContext,
  t: EnBlockToken,
  b: EnBlockToken[],
  a: EnBlockToken[],
): EnBlockHit | null {
  const n = a[0];
  if (!(n?.w === "skated")) return null;
  if (enIsBlockWord(b[0]) && (CONF_DETERMINER.has(b[0].w) || confPlainAdjective(b[0].w)))
    return null;
  if (!/^[ \t\u00a0]+$/.test(ctx.text.slice(t.end, n.start))) return null;
  return {
    start: t.start,
    end: n.end,
    alts: [`${t.text}-${n.text}`],
    key: "review_msg_closed_compound",
  };
}

// en.yaml rule en.confusedWords def confSummery
export function confSummery(
  ctx: DetectContext,
  t: EnBlockToken,
  b: EnBlockToken[],
  a: EnBlockToken[],
): EnBlockHit | null {
  if (!(ctx.text[t.start - 1] !== "-")) return null;
  if (enIsBlockWord(a[0]) && CONF_SEASONAL.has(a[0].w) && ctx.text[t.end] !== "-") return null;
  if (
    enIsBlockWord(b[0]) &&
    /^(?:very|so|too|quite|more|most|rather|really|pretty|feel|feels|felt|look|looks|looked|sound|sounds|seem|seems)$/.test(
      b[0].w,
    )
  )
    return null;
  if (
    enIsBlockWord(b[0]) &&
    /^(?:is|was|are|were|be|been|it's|that's)$/.test(b[0].w) &&
    (confEnds(a[0]) || /^(?:and|but|with|today|again|now|outside)$/.test(a[0].w))
  )
    return null;
  return confHit(t, ["summary"]);
}

// en.yaml rule en.confusedWords def confTheses
export function confTheses(
  ctx: DetectContext,
  t: EnBlockToken,
  b: EnBlockToken[],
  a: EnBlockToken[],
): EnBlockHit | null {
  const n = a[0];
  if (!enIsBlockWord(n)) return null;
  const info = englishWordInfo(n.w);
  if (!(info ? info.plural : /[^s]s$/.test(n.w))) return null;
  const p = b[0];
  if (
    enIsBlockWord(p) &&
    (CONF_DETERMINER.has(p.w) ||
      /^(?:these|those|some|many|several|two|three|both|all|her|doctoral|master's|masters|phd|other|such|their|whose)$/.test(
        p.w,
      ) ||
      /['’]s$/.test(p.w) ||
      /^\d/.test(p.w) ||
      confPlainAdjective(p.w))
  )
    return null;
  return confHit(t, ["these"]);
}

// en.yaml rule en.confusedWords def confBrandish
export function confBrandish(
  ctx: DetectContext,
  t: EnBlockToken,
  b: EnBlockToken[],
  a: EnBlockToken[],
): EnBlockHit | null {
  if (!(enIsBlockWord(a[0]) && /^(?:him|her|them|us|me|you)$/.test(a[0].w))) return null;
  if (!(enIsBlockWord(a[1]) && /^(?:a|an|as|with)$/.test(a[1].w))) return null;
  return confHit(t, [CONF_BRAND[t.w]]);
}

// en.yaml rule en.confusedWords def confDeny
export function confDeny(
  ctx: DetectContext,
  t: EnBlockToken,
  b: EnBlockToken[],
  a: EnBlockToken[],
): EnBlockHit | null {
  const i =
    enIsBlockWord(a[0]) &&
    /^(?:the|an|your|their|his|her|my|our|this|that|any|every|all)$/.test(a[0].w)
      ? 1
      : 0;
  if (!(enIsBlockWord(a[i]) && /^offers?$/.test(a[i].w))) return null;
  const gerundSubject =
    t.w === "denying" &&
    (confOpens(b[0]) || (enIsBlockWord(b[0]) && confIsAdverb(b[0].w) && confOpens(b[1])));
  if (
    !gerundSubject &&
    enIsBlockWord(a[i + 1]) &&
    /^(?:was|is|were|are|had|has|existed|exists|ever)$/.test(a[i + 1].w)
  )
    return null;
  return confHit(t, [...CONF_DENY[t.w]]);
}

// en.yaml rule en.confusedWords def confDissemble
export function confDissemble(
  ctx: DetectContext,
  t: EnBlockToken,
  b: EnBlockToken[],
  a: EnBlockToken[],
): EnBlockHit | null {
  const n = a[0];
  const later = /\bassembl/i.test(ctx.text.slice(t.end, t.end + 80));
  const object =
    enIsBlockWord(n) &&
    /^(?:the|a|an|my|this|that|it|them|these|those|his|her|our|their|your|from)$/.test(n.w);
  if (!(later || object || ctx.text[t.end] === "/")) return null;
  return confHit(t, [t.w.replace(/^dissembl/, "disassembl")]);
}

// en.yaml rule en.confusedWords def confEverRelative
export function confEverRelative(
  ctx: DetectContext,
  t: EnBlockToken,
  b: EnBlockToken[],
  a: EnBlockToken[],
): EnBlockHit | null {
  const rel = a[0];
  if (!(enIsBlockWord(rel) && /^(?:that|which|who)$/.test(rel.w))) return null;
  const n = a[1];
  if (!enIsBlockWord(n)) return null;
  if (rel.w === "that" && !/^(?:i|i've|i'm|i'd|you|we|they|he|she|you've|we've|they've)$/.test(n.w))
    return null;
  if (rel.w === "which" && /^(?:way|one|ones)$/.test(n.w)) return null;
  if (rel.w === "who" && t.w !== "whoever" && t.w !== "whatever") return null;
  return { start: t.end, end: rel.end, alts: [""] };
}

// en.yaml rule en.confusedWords def confEveryday
export function confEveryday(
  ctx: DetectContext,
  t: EnBlockToken,
  b: EnBlockToken[],
  a: EnBlockToken[],
): EnBlockHit | null {
  const n = a[0];
  const p = b[0];
  if (
    enIsBlockWord(p) &&
    /^(?:the|an?|word|is|are|was|were|be|so|very|quite|more|most|less|such|of|called|named|my|your|our|their|his|her|its)$/.test(
      p.w,
    )
  )
    return null;
  const ok =
    (enIsBlockWord(n) &&
      /^(?:is|was|feels?|seems?|brings|starts|begins)$/.test(n.w) &&
      ((confOpens(p) && /^[Ee]veryday$/.test(t.text)) ||
        (enIsBlockWord(p) && /^(?:does|did|why|and|but|because|so)$/.test(p.w)))) ||
    (enIsBlockWord(n) &&
      /^(?:we|i|you|they|he|she)$/.test(n.w) &&
      (confOpens(p) || p?.text === ",")) ||
    (t.text === "EVERYDAY" && confEnds(n) && enIsBlockWord(p) && p.text === p.text.toUpperCase());
  if (!ok) return null;
  return { ...confHit(t, ["every day"]), key: "review_msg_every_day" };
}

// en.yaml rule en.confusedWords def confComparative
export function confComparative(w: string) {
  if (!(w.length >= 5 && w.endsWith("er"))) return false;
  const info = englishWordInfo(w);
  if (!(info && !info.noun && !info.verbs.length)) return false;
  const stem = w.slice(0, -2);
  if ((stem.match(/[aeiouy]+/g) ?? []).length > 1 && !/(?:i|l|ow)$/.test(stem) && w !== "stupider")
    return false;
  return [stem, `${stem}e`, stem.replace(/(.)\1$/, "$1"), stem.replace(/i$/, "y")].some(
    (base) => englishWordInfo(base)?.adjective,
  );
}

// en.yaml rule en.confusedWords def confThatThan
export function confThatThan(
  ctx: DetectContext,
  t: EnBlockToken,
  b: EnBlockToken[],
  a: EnBlockToken[],
): EnBlockHit | null {
  const p = b[0];
  if (!(
    enIsBlockWord(p) &&
    p.text === p.w &&
    !CONF_CLAUSE_COMPARATIVE.has(p.w) &&
    confComparative(p.w)
  ))
    return null;
  if (b[1]?.w === "no" || b.slice(1, 6).some((x) => /^(?:so|such)$/.test(x.w))) return null;
  if (b.slice(1, 4).some((x) => x.w === "it" || x.w === "it's") && confFiniteClause(a)) return null;
  const n = a[0];
  if (!enIsBlockWord(n)) return null;
  if (!confThanNext(n.w)) return null;
  return { ...confHit(t, ["than"]), key: "review_msg_then_than" };
}

// en.yaml rule en.confusedWords def confFiniteClause
export function confFiniteClause(a: EnBlockToken[]) {
  const clause = a.slice(0, 8);
  const stop = clause.findIndex((x) => !enIsBlockWord(x));
  return (stop < 0 ? clause : clause.slice(0, stop)).some(
    (x) => CONF_MODAL.has(x.w) || CONF_BE_FINITE.has(x.w) || hasVerbForm(x.w, "past", "third"),
  );
}

// en.yaml rule en.confusedWords def confThanNext
export function confThanNext(w: string) {
  const info = englishWordInfo(w);
  return !(
    (info?.adjective && !info.noun) ||
    info?.adverb ||
    /^(?:way|much|is|was|it|i|you|we|they|he|she)$/.test(w)
  );
}

// en.yaml rule en.confusedWords def confThenThan
export function confThenThan(
  ctx: DetectContext,
  t: EnBlockToken,
  b: EnBlockToken[],
  a: EnBlockToken[],
): EnBlockHit | null {
  const p = b[0];
  if (!(enIsBlockWord(p) && !ctx.text.slice(p.end, t.start).includes(","))) return null;
  const n = a[0];
  if (!enIsBlockWord(n)) return null;
  const verb = enIsBlockWord(b[1]) ? englishWordInfo(b[1].w) : null;
  const compared =
    (confComparative(p.w) &&
      (!/^(?:earlier|later)$/.test(p.w) ||
        (!!verb?.verbs.some((v) => v.form === "past") && !verb.noun && !verb.adjective))) ||
    /^(?:better|worse|more|less)$/.test(p.w) ||
    (enIsBlockWord(b[1]) && /^(?:more|less)$/.test(b[1].w));
  if (!compared) return null;
  const n1 = a[1];
  const closes = confEnds(n1) || /^(?:but|and|at|in|on|too|or|for)$/.test(n1.w);
  return (/^(?:her|him|me|us|them|some|most|others|many|few|anyone|everyone)$/.test(n.w) &&
    closes) ||
    (n.w === "no" && enIsBlockWord(n1) && /^(?:better|worse)$/.test(p.w))
    ? { ...confHit(t, ["than"]), key: "review_msg_then_than" }
    : null;
}

// en.yaml rule en.confusedWords def confIts
export function confIts(
  ctx: DetectContext,
  t: EnBlockToken,
  b: EnBlockToken[],
  a: EnBlockToken[],
): EnBlockHit | null {
  const n = a[0];
  if (!enIsBlockWord(n)) return null;
  return t.w !== "its" ? confItsContraction(t, b, a, n) : confItsPossessive(t, b, a, n);
}

// en.yaml rule en.confusedWords def confItsHit
export function confItsHit(t: EnBlockToken): EnBlockHit {
  return { ...confHit(t, ["its"]), key: "review_msg_its_possessive" };
}

// en.yaml rule en.confusedWords def confItsPossessive
export function confItsPossessive(
  t: EnBlockToken,
  b: EnBlockToken[],
  a: EnBlockToken[],
  n: EnBlockToken,
): EnBlockHit | null {
  if (!(
    enIsBlockWord(b[0]) &&
    /^(?:think|thinks|hope|hopes|guess|assume|doubt|suppose|believe|bet)$/.test(b[0].w)
  ))
    return null;
  if (!/^\p{Lu}\p{Ll}/u.test(n.text)) return null;
  const rest = a.slice(1, 4);
  const tail =
    confEnds(rest[0]) ||
    (/^\d/.test(rest[0].text) && confEnds(rest[1])) ||
    (/^(?:this|next|last)$/.test(rest[0].w) && enIsBlockWord(rest[1]) && confEnds(rest[2]));
  return tail ? { ...confHit(t, ["it's"]), key: "review_msg_its_contraction" } : null;
}

// en.yaml rule en.confusedWords def confItsContraction
export function confItsContraction(
  t: EnBlockToken,
  b: EnBlockToken[],
  a: EnBlockToken[],
  n: EnBlockToken,
): EnBlockHit | null {
  const ordinal =
    /^\d+(?:st|nd|rd|th)$/.test(n.w) &&
    enIsBlockWord(a[1]) &&
    (englishWordInfo(a[1].w)?.noun ?? true) &&
    enIsBlockWord(b[0]) &&
    !confOpens(b[0]) &&
    !/^(?:think|guess|know|hope|say|said|says|believe|sure|suppose|mean|means|seems|now|so|and|but|because|that|if|when)$/.test(
      b[0].w,
    );
  const info = englishWordInfo(n.w);
  const nounOnly =
    !!info &&
    (info.noun || info.plural) &&
    !info.adjective &&
    !info.adverb &&
    !/(?:ing|ed)$/.test(n.w);
  return ordinal ||
    ((confOpens(b[0]) || b[0]?.text === ",") &&
      enIsBlockWord(a[1]) &&
      /^(?:is|was|has|are|were|have)$/.test(a[1].w) &&
      (nounOnly || (!info && !/(?:ing|ed|ly)$/.test(n.w))) &&
      !/^(?:time|everything|nothing|something|anything|one|what|who|this|that|here|there|now|all)$/.test(
        n.w,
      )) ||
    (nounOnly &&
      n.text === n.w &&
      !/^(?:in|on|at|for|from|with|by|about|of|to|up|down|out|off|over|under|there|here)$/.test(
        n.w,
      ) &&
      confEnds(a[1]) &&
      enIsBlockWord(b[0]) &&
      !CONF_CLAUSE_VERB.has(b[0].w) &&
      hasVerbForm(b[0].w, "past", "third")) ||
    (n.w === "various" && enIsBlockWord(a[1]) && !/^(?:who|that|which)$/.test(a[2]?.w ?? "")) ||
    (nounOnly &&
      a[1]?.text === "," &&
      (confListedIts(a[2]) || (a[2]?.w === "and" && confListedIts(a[3])))) ||
    (nounOnly && b[0]?.text === "," && confListedIts(b[2])) ||
    (nounOnly && b[0]?.w === "and" && b[1]?.text === "," && confListedIts(b[3]))
    ? confItsHit(t)
    : null;
}

// en.yaml rule en.confusedWords def confListedIts
export function confListedIts(x: EnBlockToken | undefined) {
  return enIsBlockWord(x) && /^it's$/.test(x.w);
}

// en.yaml rule en.confusedWords def confLets
export function confLets(
  ctx: DetectContext,
  t: EnBlockToken,
  b: EnBlockToken[],
  a: EnBlockToken[],
): EnBlockHit | null {
  const n = a[0];
  if (!enIsBlockWord(n)) return null;
  return t.w === "let's" ? confLetsObject(t, a, n) : confLetsVerb(t, b, a, n);
}

// en.yaml rule en.confusedWords def confLetsObject
export function confLetsObject(
  t: EnBlockToken,
  a: EnBlockToken[],
  n: EnBlockToken,
): EnBlockHit | null {
  if (!(
    /^(?:me|us|him|her|them|you)$/.test(n.w) &&
    enIsBlockWord(a[1]) &&
    hasVerbForm(a[1].w, "base")
  ))
    return null;
  return confHit(t, ["lets"]);
}

// en.yaml rule en.confusedWords def confLetsVerb
export function confLetsVerb(
  t: EnBlockToken,
  b: EnBlockToken[],
  a: EnBlockToken[],
  n: EnBlockToken,
): EnBlockHit | null {
  if (!(confOpens(b[0]) || (enIsBlockWord(b[0]) && CONF_LETS_CUE.has(b[0].w)))) return null;
  if (n.text !== n.w || n.w.length < 2 || a.slice(1, 3).some((x) => x.text === "=")) return null;
  const info = englishWordInfo(n.w);
  if (!(info?.verbs.some((v) => v.form === "base") && !info.plural && !CONF_OBJECT_START.has(n.w)))
    return null;
  if (
    (info.noun || info.adjective) &&
    !(enIsBlockWord(a[1]) && CONF_OBJECT_START.has(a[1].w) && a[1].text === a[1].w)
  )
    return null;
  if (
    t.w === "let" &&
    (/^(?:go|slip|fly|pass|drop|fall|rip|loose|be|know)$/.test(n.w) || !confOpens(b[0]))
  )
    return null;
  return { ...confHit(t, ["let's"]), key: "review_msg_lets_contraction" };
}

// en.yaml rule en.confusedWords def confYoure
export function confYoure(
  ctx: DetectContext,
  t: EnBlockToken,
  b: EnBlockToken[],
  a: EnBlockToken[],
): EnBlockHit | null {
  const n = a[0];
  if (!(enIsBlockWord(n) && enIsBlockWord(a[1]) && /^(?:is|was|has|had|are|were)$/.test(a[1].w)))
    return null;
  const info = englishWordInfo(n.w);
  const noun =
    /^[A-Z]{2,}$/.test(n.text) ||
    (!!info &&
      (info.noun || info.plural) &&
      !info.adjective &&
      !info.adverb &&
      !/(?:ing|ed)$/.test(n.w));
  if (!(noun && !/^(?:all|both|each|one|right|welcome|here|there|now|what|who)$/.test(n.w)))
    return null;
  return { ...confHit(t, ["your"]), key: "review_msg_your_possessive" };
}

// en.yaml rule en.confusedWords def confWere
export function confWere(
  ctx: DetectContext,
  t: EnBlockToken,
  b: EnBlockToken[],
  a: EnBlockToken[],
): EnBlockHit | null {
  if (!(confOpens(b[0]) && enIsBlockWord(a[0]) && /^(?:a|an|the)$/.test(a[0].w))) return null;
  const i = confCount(a, 1, 5, enIsBlockWord);
  if (a.slice(1, i).some((x) => confWereBlocker(x.w))) return null;
  if (i < 3 || (a[i] && !/^[.!]$/.test(a[i].text))) return null;
  return confHit(t, ["we're"]);
}

// en.yaml rule en.confusedWords def confWereBlocker
export function confWereBlocker(w: string) {
  const info = englishWordInfo(w);
  return (
    (!!info?.verbs.some(
      (v) => v.form === "past" || v.form === "participle" || v.form === "third",
    ) &&
      !info.noun) ||
    /(?:ed|ing)$/.test(w) ||
    /^(?:there|here|you|we|they|it|he|she|i)$/.test(w)
  );
}

// en.yaml rule en.confusedWords def confOpenDevice
export function confOpenDevice(
  ctx: DetectContext,
  t: EnBlockToken,
  b: EnBlockToken[],
  a: EnBlockToken[],
): EnBlockHit | null {
  if (!(
    enIsBlockWord(a[0]) &&
    /^(?:the|my|your|our|their|his|her)$/.test(a[0].w) &&
    enIsBlockWord(a[1]) &&
    CONF_DEVICE.has(a[1].w)
  ))
    return null;
  if (
    enIsBlockWord(a[2]) &&
    !/^(?:to|when|and|so|for|because|now|please|before|after|while|if|again|then|or)$/.test(a[2].w)
  )
    return null;
  return confHit(t, [CONF_TURN[t.w]]);
}

// en.yaml rule en.confusedWords def CONF_HANDLERS
export const CONF_HANDLERS = {
  advice: confNounForVerb,
  belief: confNounForVerb,
  breath: confNounForVerb,
  intent: confNounForVerb,
  emphasis: confNounForVerb,
  response: confNounForVerb,
  thing: confNounForVerb,
  advise: confVerbForNoun,
  believe: confVerbForNoun,
  breathe: confVerbForNoun,
  intend: confVerbForNoun,
  bias: confBeAdjective,
  concern: confBeAdjective,
  prejudice: confBeAdjective,
  worry: confBeAdjective,
  shock: confBeAdjective,
  brandish: confBrandish,
  brandishes: confBrandish,
  brandished: confBrandish,
  brandishing: confBrandish,
  deny: confDeny,
  denies: confDeny,
  denied: confDeny,
  denying: confDeny,
  open: confOpenDevice,
  opens: confOpenDevice,
  opened: confOpenDevice,
  opening: confOpenDevice,
  effect: confEffect,
  effects: confEffect,
  affect: confAffect,
  affects: confAffect,
  safe: confSafe,
  weight: confWeight,
  bough: confBough,
  fell: confFell,
  quiet: confQuiet,
  find: confFind,
  hop: confHop,
  hops: confHop,
  hope: confHop,
  hopes: confHop,
  hoped: confHop,
  hoping: confHop,
  cant: confCant,
  rogue: confRogue,
  roller: confRoller,
  summery: confSummery,
  theses: confTheses,
  whatever: confEverRelative,
  whoever: confEverRelative,
  whenever: confEverRelative,
  wherever: confEverRelative,
  everyday: confEveryday,
  that: confThatThan,
  then: confThenThan,
  its: confIts,
  "it's": confIts,
  lets: confLets,
  "let's": confLets,
  let: confLets,
  "you're": confYoure,
  were: confWere,
} as Readonly<Record<string, typeof confNounForVerb>>;

// en.yaml rule en.confusedWords def CONF_QUOTE
export const CONF_QUOTE = /^["“”'‘’]$/;

// en.yaml rule en.confusedWords def confMentioned
export function confMentioned(ctx: DetectContext, h: EnBlockHit) {
  const b = enBlockTokensBefore(ctx, h.start).slice(0, 2);
  const a = enBlockTokensAfter(ctx, h.end).slice(0, 2);
  return b.some((t) => CONF_QUOTE.test(t.text)) && a.some((t) => CONF_QUOTE.test(t.text));
}

// en.yaml rule en.confusedWords def confMake
export function confMake(
  ctx: DetectContext,
  start: number,
  end: number,
  alternatives: string[],
  messageKey: RawFinding["messageKey"] | undefined,
): RawFinding | null {
  const typed = ctx.source.slice(start, end);
  const cased = alternatives.map((alt) => caseLike(typed, alt));
  if (cased.includes(typed)) return null;
  return finding(
    "englishConfusedWords",
    messageKey ?? "review_msg_confused_word",
    start,
    end,
    cased,
    {
      ...(cased.length > 1 ? { requiresChoice: true as const } : {}),
      context: { start: Math.max(0, start - 80), end: Math.min(ctx.text.length, end + 80) },
    },
  );
}

// en.yaml rule en.contextualConfusions def CONF2_AUX
export const CONF2_AUX = new Set([...CONF2_MODALS, ...CONF2_BE, ...CONF2_HAVE, ...CONF2_AUX_MORE]);

// en.yaml rule en.contextualConfusions def CONF2_CLOSED
export const CONF2_CLOSED = new Set([
  ...CONF2_DET,
  ...CONF2_SUBJECTS,
  ...CONF2_OBJECTS,
  ...CONF2_WH,
  ...CONF2_AUX,
  ...CONF2_ADVERBS,
  ...CONF2_PREPOSITIONS,
  ...CONF2_CLOSED_MORE,
]);

// en.yaml rule en.contextualConfusions def CONF2_CLAUSE_LEMMAS
export const CONF2_CLAUSE_LEMMAS = new Set([...CONF2_BARE_CLAUSE, ...CONF2_OBJECT_FIRST]);

// en.yaml rule en.contextualConfusions def CONF2_THERE_BLOCK
export const CONF2_THERE_BLOCK = new Set([...CONF2_PLACE_LEMMAS, ...CONF2_THERE_BLOCK_MORE]);

// en.yaml rule en.contextualConfusions def CONF2_SHUT_AUX
export const CONF2_SHUT_AUX = new Set([...CONF2_MODALS, ...CONF2_HAVE, ...CONF2_SHUT_AUX_MORE]);

// en.yaml rule en.contextualConfusions def CONF2_SHUT_OBJECT
export const CONF2_SHUT_OBJECT = new Set([...CONF2_DET, ...CONF2_SHUT_OBJECT_MORE]);

// en.yaml rule en.contextualConfusions def CONF2_RELAY_LEAD
export const CONF2_RELAY_LEAD = new Set([...CONF2_MODALS, ...CONF2_RELAY_LEAD_MORE]);

// en.yaml rule en.contextualConfusions def CONF2_THEM_LEAD
export const CONF2_THEM_LEAD = new Set([...CONF2_MODALS, ...CONF2_THEM_LEAD_MORE]);

// en.yaml rule en.contextualConfusions def CONF2_FINITE
export const CONF2_FINITE = new Set([
  ...CONF2_MODALS,
  ...CONF2_BE,
  ...CONF2_HAVE,
  ...CONF2_FINITE_MORE,
]);

// en.yaml rule en.contextualConfusions def conf2LemmaIn
export function conf2LemmaIn(word: string, lemmas: ReadonlySet<string>) {
  return (
    lemmas.has(word) ||
    (englishWordInfo(word)?.verbs.some((verb) => lemmas.has(verb.lemma)) ?? false)
  );
}

// en.yaml rule en.contextualConfusions def conf2Adjective
export function conf2Adjective(word: string) {
  return englishWordInfo(word)?.adjective ?? false;
}

// en.yaml rule en.contextualConfusions def conf2Nounish
export function conf2Nounish(word: string) {
  if (!(!CONF2_CLOSED.has(word) && !CONF2_TIME.has(word))) return false;
  const entry = englishWordInfo(word);
  return entry
    ? (!entry.verbs.length && !entry.noun && !entry.adjective && !entry.adverb) ||
        ((entry.noun || entry.plural) && !entry.adverb && !entry.adjective)
    : /^[a-z]{4,}$/.test(word);
}

// en.yaml rule en.contextualConfusions def conf2PureFinite
export function conf2PureFinite(word: string) {
  const entry = englishWordInfo(word);
  return (
    !!entry &&
    entry.verbs.some((verb) => verb.form === "past" || verb.form === "third") &&
    !entry.noun &&
    !entry.plural &&
    !entry.adjective
  );
}

// en.yaml rule en.contextualConfusions def conf2NounPhrase
export function conf2NounPhrase(
  next: readonly EnClauseWord[],
  from: number,
  compound: boolean,
): number {
  const entry = next[from] && englishWordInfo(next[from].w);
  const k1 =
    entry && entry.adverb && !entry.adjective && !entry.noun && !CONF2_CLOSED.has(next[from].w)
      ? from + 1
      : from;
  const modifier = next[k1]?.w;
  const k2 =
    modifier &&
    next[k1 + 1] &&
    !CONF2_CLOSED.has(modifier) &&
    (conf2Adjective(modifier) || hasVerbForm(modifier, "past", "participle")) &&
    conf2Nounish(next[k1 + 1].w)
      ? k1 + 1
      : k1;
  if (!(next[k2] && conf2Nounish(next[k2].w))) return -1;
  const k3 =
    compound && next[k2 + 1] && conf2Nounish(next[k2 + 1].w) && !englishWordInfo(next[k2].w)?.plural
      ? k2 + 1
      : k2;
  const after = next[k3 + 1]?.w ?? "";
  if (
    hasVerbForm(next[k3].w, "ing") &&
    (CONF2_DET.has(after) || CONF2_OBJECTS.has(after) || after === "to")
  )
    return -1;
  return k3;
}

// en.yaml rule en.contextualConfusions def conf2SubjectPhrase
export function conf2SubjectPhrase(next: readonly EnClauseWord[], compound: boolean): boolean {
  return (
    (compound && conf2SubjectPhrase(next, false)) ||
    conf2SubjectAt(next, conf2NounPhrase(next, 0, compound))
  );
}

// en.yaml rule en.contextualConfusions def conf2SubjectAt
export function conf2SubjectAt(next: readonly EnClauseWord[], head: number) {
  if (!(head >= 0)) return false;
  const verb = next[head + 1]?.w;
  if (!(verb && !CONF2_COMPOUND_PARTICIPLES.has(verb))) return false;
  const like = hasVerbForm(verb, "third") && next[head + 2]?.w === "like";
  return (
    /^(?:is|was|are|were|has|have|had)$/.test(verb) ||
    (englishWordInfo(next[head].w)?.plural
      ? (hasVerbForm(verb, "third") && conf2PureFinite(verb)) || like
      : conf2PureFinite(verb) || like)
  );
}

// en.yaml rule en.contextualConfusions def conf2ObjectVerb
export function conf2ObjectVerb(
  text: string,
  verb: EnClauseWord | undefined,
  before: EnClauseWord | undefined,
  blocked: ReadonlySet<string>,
) {
  if (!(
    verb &&
    !CONF2_CLOSED.has(verb.w) &&
    !CONF2_LOCATIVE_LEAD.has(verb.w) &&
    englishWordInfo(verb.w)?.verbs.length
  ))
    return false;
  if (!(!conf2LemmaIn(verb.w, blocked) && !conf2LemmaIn(verb.w, CONF2_PLACE_LEMMAS))) return false;
  if (
    before &&
    (CONF2_DET.has(before.w) ||
      (conf2Adjective(before.w) &&
        !CONF2_CLOSED.has(before.w) &&
        !englishWordInfo(before.w)?.verbs.length &&
        !englishWordInfo(before.w)?.adverb))
  )
    return false;
  return !(hasVerbForm(verb.w, "ing") && enClauseOpensAt(text, verb.start));
}

// en.yaml rule en.contextualConfusions def conf2GerundHeadOk
export function conf2GerundHeadOk(
  ctx: DetectContext,
  h: EnWordsAround,
  verb: EnClauseWord | undefined,
) {
  const k = conf2NounPhrase(h.N, 0, true);
  const head = h.N[k];
  const after = h.N[k + 1]?.w ?? "";
  return (
    !head ||
    !hasVerbForm(head.w, "ing") ||
    after === "of" ||
    (!!verb &&
      hasVerbForm(verb.w, "past", "participle") &&
      (enClauseClosesAt(ctx.text, head.end) ||
        CONF2_FINITE.has(after) ||
        CONF2_PREPOSITIONS.has(after)))
  );
}

// en.yaml rule en.contextualConfusions def conf2PrepositionObject
export function conf2PrepositionObject(ctx: DetectContext, h: EnWordsAround) {
  const p0 = h.P[0];
  const p1 = h.P[1];
  if (!(p0 && p1 && CONF2_THERE_PREPOSITIONS.has(p0.w) && !enClauseOpensAt(ctx.text, p0.start)))
    return false;
  if (!(
    !CONF2_LOCATIVE_LEAD.has(p1.w) &&
    !CONF2_CLOSED.has(p1.w) &&
    !conf2LemmaIn(p1.w, CONF2_THERE_BLOCK)
  ))
    return false;
  const from = /^(?:most|more|less|least)$/.test(h.N[0]?.w ?? "") ? 1 : 0;
  const phrase = conf2NounPhrase(h.N, from, true);
  const entry = h.N[from] && englishWordInfo(h.N[from].w);
  const head =
    phrase < 0 && entry?.noun && !entry.adverb && !CONF2_TIME.has(h.N[from].w) ? from : phrase;
  if (!(head >= 0)) return false;
  const next = h.N[head + 1]?.w ?? "";
  return (
    (!/^(?:from|to)$/.test(p0.w) && enClauseClosesAt(ctx.text, h.N[head].end)) ||
    CONF2_PREPOSITIONS.has(next) ||
    next === "and" ||
    next === "or"
  );
}

// en.yaml rule en.contextualConfusions def conf2ClauseStart
export function conf2ClauseStart(ctx: DetectContext, start: number, h: EnWordsAround) {
  return enClauseOpensAt(ctx.text, start) || CONF2_CONJUNCTIONS.has(h.P[0]?.w ?? "");
}

// en.yaml rule en.contextualConfusions def conf2Emit
export function conf2Emit(
  ctx: DetectContext,
  start: number,
  end: number,
  ruleId: RawFinding["ruleId"],
  messageKey: RawFinding["messageKey"],
  replacements: readonly string[],
  evidence: readonly [number, number],
): RawFinding | null {
  if (!(start >= ctx.from && start < ctx.to)) return null;
  const from = Math.min(start, evidence[0]);
  const to = Math.max(end, evidence[1]);
  if (hasUserOrCasedWord(ctx, ctx.text.slice(from, to))) return null;
  if (!(!enGluedAfter(ctx.text, end) && !namedExampleBefore(ctx.text, from))) return null;
  const typed = ctx.text.slice(start, end);
  const casing = detectWordCase(typed);
  const previous = enClauseWordsBefore(ctx.text, start, 1)[0];
  if (
    casing === "title" &&
    previous &&
    /^[a-z]/.test(previous.raw) &&
    !enClauseOpensAt(ctx.text, start)
  )
    return null;
  const curly = typed.includes("’");
  const alternatives = replacements.map((replacement) =>
    curly
      ? applyWordCase(replacement, casing).replace(/'/g, "’")
      : applyWordCase(replacement, casing),
  );
  return finding(ruleId, messageKey, start, end, alternatives, {
    ...(alternatives.length > 1 ? { requiresChoice: true as const } : {}),
    context: { start: Math.max(0, from - 48), end: Math.min(ctx.text.length, to + 16) },
  });
}

// en.yaml rule en.contextualConfusions def conf2Typo
export function conf2Typo(
  ctx: DetectContext,
  start: number,
  end: number,
  replacement: string,
  first: EnClauseWord | undefined,
  last: EnClauseWord | undefined,
) {
  return conf2Emit(
    ctx,
    start,
    end,
    "englishUsagePhrases",
    "review_msg_typo",
    [replacement],
    [first?.start ?? start, last?.end ?? end],
  );
}

// en.yaml rule en.contextualConfusions def conf2TheirFamily
export function conf2TheirFamily(
  ctx: DetectContext,
  start: number,
  end: number,
  h: EnWordsAround,
  key: RawFinding["messageKey"],
  replacement: string,
  first: EnClauseWord | undefined,
) {
  return conf2Emit(
    ctx,
    start,
    end,
    "englishTheirThereTheyAre",
    key,
    [replacement],
    [first?.start ?? start, h.N[0]?.end ?? end],
  );
}

// en.yaml rule en.contextualConfusions def conf2Skip
export function conf2Skip(
  list: readonly EnClauseWord[],
  set: ReadonlySet<string>,
  i: number,
): number {
  return list[i] && set.has(list[i].w) ? conf2Skip(list, set, i + 1) : i;
}

// en.yaml rule en.contextualConfusions def CONF2_PERSONAL_BE
export const CONF2_PERSONAL_BE = /^(?:i'm|you're|we're|they're|he's|she's)$/;

// en.yaml rule en.contextualConfusions def conf2Cold
export function conf2Cold(
  ctx: DetectContext,
  word: string,
  start: number,
  end: number,
  h: EnWordsAround,
): RawFinding | null {
  const p0 = h.P[0];
  const p1 = h.P[1];
  const n0 = h.N[0];
  if (!(p0 && n0 && !CONF2_COLD_COMPOUNDS.has(n0.w))) return null;
  const subject =
    /^(?:i|we|they|he|she)$/.test(p0.w) ||
    (/^(?:it|you)$/.test(p0.w) &&
      (enClauseOpensAt(ctx.text, p0.start) ||
        /^(?:and|but|so|if|when|because|that)$/.test(p1?.w ?? "")));
  if (!(subject && (CONF2_ADVERBS.has(n0.w) || hasVerbForm(n0.w, "base")))) return null;
  return conf2Typo(ctx, start, end, "could", p0, n0);
}

// en.yaml rule en.contextualConfusions def conf2Dos
export function conf2Dos(
  ctx: DetectContext,
  word: string,
  start: number,
  end: number,
  h: EnWordsAround,
): RawFinding | null {
  const subject = h.P[conf2Skip(h.P, CONF2_ADVERBS, 0)];
  if (!(subject && /^(?:he|she|it)$/.test(subject.w))) return null;
  const typed = ctx.text.slice(start, end);
  if (typed === "DOS" && subject.raw !== subject.raw.toUpperCase()) return null;
  return conf2Typo(ctx, start, end, "does", subject, undefined);
}

// en.yaml rule en.contextualConfusions def conf2Wok
export function conf2Wok(
  ctx: DetectContext,
  word: string,
  start: number,
  end: number,
  h: EnWordsAround,
): RawFinding | null {
  const lead = h.P[conf2Skip(h.P, CONF2_ADVERBS, 0)];
  if (!lead) return null;
  const n0 = h.N[0]?.w ?? "";
  const ok =
    (CONF2_SUBJECTS.has(lead.w) &&
      (!/^(?:it|you)$/.test(lead.w) || enClauseOpensAt(ctx.text, lead.start))) ||
    (lead.w !== "to" &&
      CONF2_AUX.has(lead.w) &&
      !(/^(?:do|does|did)$/.test(lead.w) && enClauseOpensAt(ctx.text, lead.start))) ||
    (lead.w === "to" &&
      (enClauseOpensAt(ctx.text, lead.start) ||
        /^(?:here|there|on|from|at|with|around|for|late|hard|together|remotely|fast|well|better|overtime)$/.test(
          n0,
        )));
  if (!ok) return null;
  return conf2Typo(ctx, start, end, "work", lead, undefined);
}

// en.yaml rule en.contextualConfusions def conf2Rally
export function conf2Rally(
  ctx: DetectContext,
  word: string,
  start: number,
  end: number,
  h: EnWordsAround,
): RawFinding | null {
  const n0 = h.N[0];
  const entry = n0 && englishWordInfo(n0.w);
  if (!(
    entry &&
    (hasVerbForm(n0.w, "ing") || (entry.adjective && !entry.noun && !entry.verbs.length))
  ))
    return null;
  const i = h.P[0]?.w === "not" ? 1 : 0;
  const p = h.P[i];
  if (!p) return null;
  const be =
    CONF2_BE.has(p.w) ||
    /^(?:i'm|you're|we're|they're|he's|she's|it's|that's)$/.test(p.w) ||
    (CONF2_SUBJECTS.has(p.w) && CONF2_BE.has(h.P[i + 1]?.w ?? ""));
  if (!be) return null;
  return conf2Typo(ctx, start, end, "really", p, n0);
}

// en.yaml rule en.contextualConfusions def conf2Pleas
export function conf2Pleas(
  ctx: DetectContext,
  word: string,
  start: number,
  end: number,
  h: EnWordsAround,
): RawFinding | null {
  const n0 = h.N[0];
  if (!(n0 && hasVerbForm(n0.w, "base") && !CONF2_PLEAS_INTRANSITIVE.has(n0.w))) return null;
  const n1 = h.N[1];
  if (n1 && CONF2_PREPOSITIONS.has(n1.w)) return null;
  const p0 = h.P[0]?.w ?? "";
  if (!(enClauseOpensAt(ctx.text, start) || /^(?:you|and|but|so|then|now|just|kindly)$/.test(p0)))
    return null;
  return conf2Typo(ctx, start, end, "please", undefined, n0);
}

// en.yaml rule en.contextualConfusions def conf2Boarder
export function conf2Boarder(
  ctx: DetectContext,
  word: string,
  start: number,
  end: number,
  h: EnWordsAround,
): RawFinding | null {
  const n0 = h.N[0];
  const n1 = h.N[1];
  const n2 = h.N[2];
  const p = h.P[0] && CONF2_DET.has(h.P[0].w) ? h.P[1] : h.P[0];
  const ok =
    (!!p && /^cross(?:es|ed|ing)?$/.test(p.w)) ||
    (!!n0 &&
      !!n1 &&
      (/^(?:between|around|along|across)$/.test(n0.w) ||
        (n0.w === "of"
          ? !CONF2_BOARDING_PLACES.has(n2?.w ?? n1.w)
          : n0.w === "with"
            ? true
            : n0.w === "on"
              ? CONF2_DIRECTIONS.has(n1.w) || CONF2_DIRECTIONS.has(n2?.w ?? "")
              : false)));
  if (!ok) return null;
  return conf2Typo(ctx, start, end, word.replace("boarder", "border"), p, n0);
}

// en.yaml rule en.contextualConfusions def conf2Thieve
export function conf2Thieve(
  ctx: DetectContext,
  word: string,
  start: number,
  end: number,
  h: EnWordsAround,
): RawFinding | null {
  const p0 = h.P[0];
  if (!p0) return null;
  const p1 = h.P[1];
  if (!(
    CONF2_DET.has(p0.w) ||
    (conf2Adjective(p0.w) && !englishWordInfo(p0.w)?.verbs.length && CONF2_DET.has(p1?.w ?? ""))
  ))
    return null;
  return conf2Typo(ctx, start, end, "thief", p0, undefined);
}

// en.yaml rule en.contextualConfusions def conf2Threat
export function conf2Threat(
  ctx: DetectContext,
  word: string,
  start: number,
  end: number,
  h: EnWordsAround,
): RawFinding | null {
  const n0 = h.N[0];
  if (!(n0 && !CONF2_THREAT_COMPOUNDS.has(n0.w))) return null;
  const i = h.P[0]?.w === "not" ? 1 : 0;
  const modal = h.P[i];
  const s = h.P[i + 1];
  if (!(modal && s)) return null;
  if (!(
    (CONF2_MODALS.has(modal.w) && !CONF2_WH.has(s.w) && !enClauseOpensAt(ctx.text, modal.start)) ||
    (CONF2_SUBJECTS.has(modal.w) && CONF2_MODALS.has(s.w))
  ))
    return null;
  return conf2Emit(
    ctx,
    start,
    end,
    "englishUsagePhrases",
    "review_msg_contextual_grammar",
    ["threaten", "treat"],
    [s.start, n0.end],
  );
}

// en.yaml rule en.contextualConfusions def conf2Principle
export function conf2Principle(
  ctx: DetectContext,
  word: string,
  start: number,
  end: number,
  h: EnWordsAround,
): RawFinding | null {
  const p0 = h.P[0];
  const n0 = h.N[0];
  if (!(p0 && n0 && CONF2_DET.has(p0.w) && n0.w !== "worth")) return null;
  if (!(conf2Nounish(n0.w) || englishWordInfo(n0.w)?.noun)) return null;
  if (CONF2_CLOSED.has(n0.w) || hasVerbForm(n0.w, "third", "past", "ing") || n0.w.endsWith("ing"))
    return null;
  return conf2Typo(ctx, start, end, "principal", p0, n0);
}

// en.yaml rule en.contextualConfusions def conf2Shutdown
export function conf2Shutdown(
  ctx: DetectContext,
  word: string,
  start: number,
  end: number,
  h: EnWordsAround,
): RawFinding | null {
  const n0 = h.N[0];
  if (!(n0 && CONF2_SHUT_OBJECT.has(n0.w))) return null;
  const lead = h.P[conf2ShutLead(h.P, 0)];
  if (!(lead && CONF2_SHUT_AUX.has(lead.w))) return null;
  return conf2Emit(
    ctx,
    start,
    end,
    "englishContextualCompounds",
    "review_msg_compounds",
    ["shut down"],
    [lead.start, n0.end],
  );
}

// en.yaml rule en.contextualConfusions def conf2ShutLead
export function conf2ShutLead(p: readonly EnClauseWord[], i: number): number {
  return i < 2 &&
    p[i] &&
    (/^(?:not|never|just|already|also|still)$/.test(p[i].w) ||
      CONF2_SUBJECTS.has(p[i].w) ||
      (i === 0 && /^[A-Z][a-z]+$/.test(p[i].raw)))
    ? conf2ShutLead(p, i + 1)
    : i;
}

// en.yaml rule en.contextualConfusions def conf2Though
export function conf2Though(
  ctx: DetectContext,
  word: string,
  start: number,
  end: number,
  h: EnWordsAround,
): RawFinding | null {
  const p0 = h.P[0];
  const p1 = h.P[1];
  const n0 = h.N[0];
  if (!(p0 && n0 && CONF2_THOUGHT_NEXT.has(n0.w) && /^(?:i|we|they|you|he|she)$/.test(p0.w)))
    return null;
  if (
    p0.w === "you" &&
    !enClauseOpensAt(ctx.text, p0.start) &&
    !/^(?:and|but|so|then|if|when|because|that)$/.test(p1?.w ?? "")
  )
    return null;
  return conf2Typo(ctx, start, end, "thought", p0, n0);
}

// en.yaml rule en.contextualConfusions def conf2Heart
export function conf2Heart(
  ctx: DetectContext,
  word: string,
  start: number,
  end: number,
  h: EnWordsAround,
): RawFinding | null {
  if (!(h.N[0]?.w === "of")) return null;
  const i = conf2Skip(h.P, CONF2_HEART_ADVERBS, 0);
  const p = h.P[i];
  if (!p) return null;
  const ok =
    /^(?:(?:i|you|we|they)'ve|(?:i|you|we|they|he|she)'d)$/.test(p.w) ||
    (CONF2_HAVE.has(p.w) && i > 0 && CONF2_SUBJECTS.has(h.P[i + 1]?.w ?? "")) ||
    (CONF2_SUBJECTS.has(p.w) && CONF2_HAVE.has(h.P[i + 1]?.w ?? "")) ||
    (h.P[i + 1]?.w === "the" && CONF2_HAVE.has(h.P[i + 2]?.w ?? ""));
  if (!ok) return null;
  return conf2Typo(ctx, start, end, "heard", h.P[Math.min(h.P.length - 1, i + 2)], h.N[0]);
}

// en.yaml rule en.contextualConfusions def conf2Mach
export function conf2Mach(
  ctx: DetectContext,
  word: string,
  start: number,
  end: number,
  h: EnWordsAround,
): RawFinding | null {
  const p0 = h.P[0];
  if (!(p0?.w === "how" && !/^[ \t\u00a0]*\d/.test(ctx.text.slice(end, end + 4)))) return null;
  if (/^[A-Z][a-z]/.test(ctx.text.slice(start, end)) && /^[a-z]/.test(p0.raw)) return null;
  if (!(word !== "match" || conf2MuchNoun(h))) return null;
  return conf2Typo(ctx, start, end, "much", p0, undefined);
}

// en.yaml rule en.contextualConfusions def conf2MuchNoun
export function conf2MuchNoun(h: EnWordsAround) {
  const n0 = h.N[0];
  if (!n0) return false;
  const n1 = h.N[1];
  const entry = englishWordInfo(n0.w);
  const singular = entry
    ? entry.noun && !entry.plural && !hasVerbForm(n0.w, "third", "past", "ing")
    : /^[a-z]{4,}$/.test(n0.w);
  if (!(
    n0.w === "of" ||
    CONF2_MUCH_NEXT.has(n0.w) ||
    (singular && CONF2_MUCH_CLAUSE.has(n1?.w ?? ""))
  ))
    return false;
  return true;
}

// en.yaml rule en.contextualConfusions def conf2Exited
export function conf2Exited(
  ctx: DetectContext,
  word: string,
  start: number,
  end: number,
  h: EnWordsAround,
): RawFinding | null {
  const i0 = conf2Skip(h.P, CONF2_NOT, 0);
  const intense = CONF2_INTENSIFIERS.has(h.P[i0]?.w ?? "");
  const i = conf2Skip(h.P, CONF2_INTENSIFIERS, i0);
  const be = h.P[i];
  if (!(be && (CONF2_BE.has(be.w) || CONF2_PERSONAL_BE.test(be.w) || CONF2_EXCITED_LINK.has(be.w))))
    return null;
  const n = h.N[0]?.w;
  const personal =
    CONF2_PERSONAL_BE.test(be.w) || /^(?:i|you|we|they|he|she)$/.test(h.P[i + 1]?.w ?? "");
  if (!(intense || n === "about" || n === "that" || ((n === "for" || n === "to") && personal)))
    return null;
  return conf2Typo(ctx, start, end, "excited", be, h.N[0]);
}

// en.yaml rule en.contextualConfusions def conf2Ready
export function conf2Ready(
  ctx: DetectContext,
  word: string,
  start: number,
  end: number,
  h: EnWordsAround,
): RawFinding | null {
  const p0 = h.P[0];
  const n0 = h.N[0];
  if (!(
    p0?.w === "all" &&
    n0 &&
    !CONF2_CLOSED.has(n0.w) &&
    !CONF2_READY_NOT.has(n0.w) &&
    conf2Adjective(n0.w)
  ))
    return null;
  return conf2Emit(
    ctx,
    p0.start,
    end,
    "englishUsagePhrases",
    "review_msg_typo",
    ["already"],
    [p0.start, n0.end],
  );
}

// en.yaml rule en.contextualConfusions def conf2Way
export function conf2Way(
  ctx: DetectContext,
  word: string,
  start: number,
  end: number,
  h: EnWordsAround,
): RawFinding | null {
  const p0 = h.P[0];
  if (!(p0?.w === "now")) return null;
  const p1 = h.P[1];
  const p2 = h.P[2];
  const n0 = h.N[0];
  const n1 = h.N[1];
  const ok =
    ((p1?.w === "in" || p1?.w === "of") && p2?.w !== "as") ||
    (!!n0 &&
      (/^(?:of|for|around)$/.test(n0.w)
        ? true
        : n0.w === "to"
          ? !n1 || !(conf2Adjective(n1.w) && !englishWordInfo(n1.w)?.verbs.length)
          : /s$/.test(n0.w)
            ? !!englishWordInfo(n0.w)?.plural || (!englishWordInfo(n0.w) && conf2Nounish(n0.w))
            : false));
  if (!ok) return null;
  return conf2Emit(
    ctx,
    p0.start,
    p0.end,
    "englishUsagePhrases",
    "review_msg_typo",
    ["no"],
    [p0.start, end],
  );
}

// en.yaml rule en.contextualConfusions def conf2Do
export function conf2Do(
  ctx: DetectContext,
  word: string,
  start: number,
  end: number,
  h: EnWordsAround,
): RawFinding | null {
  const n0 = h.N[0];
  const n1 = h.N[1];
  const p0 = h.P[0];
  if (!(n0?.w === "to" && n1 && p0 && !CONF2_OBJECTS.has(n1.w))) return null;
  const p1 = h.P[1];
  const next = englishWordInfo(n1.w);
  if (next?.verbs.some((v) => v.form === "base") && !next.noun && !next.adjective) return null;
  if (/^(?:had|made|let|helped|did|done|been|used|got)$/.test(p0.w)) return null;
  const ok =
    hasVerbForm(p0.w, "past") ||
    (hasVerbForm(p0.w, "base") && CONF2_MODALS.has(p1?.w ?? "")) ||
    (!!englishWordInfo(p0.w)?.adverb &&
      !CONF2_CLOSED.has(p0.w) &&
      hasVerbForm(p1?.w ?? "", "past"));
  if (!ok) return null;
  return conf2Typo(ctx, start, end, "due", p0, n1);
}

// en.yaml rule en.contextualConfusions def conf2Waist
export function conf2Waist(
  ctx: DetectContext,
  word: string,
  start: number,
  end: number,
  h: EnWordsAround,
): RawFinding | null {
  const n0 = h.N[0];
  const n1 = h.N[1];
  if (!(n0?.w === "of" && n1 && !CONF2_WAIST_NOT.has(n1.w))) return null;
  const p0 = h.P[0]?.w ?? "";
  if (/^(?:the|her|his|my|your|its|their|our)$/.test(p0)) return null;
  const evaluative = p0 === "a" || p0 === "an" || CONF2_WASTE_ADJECTIVES.has(p0);
  if (/^(?:her|his|my|your|its|their|our)$/.test(n1.w) && !evaluative) return null;
  if (p0 && conf2Adjective(p0) && !CONF2_WASTE_ADJECTIVES.has(p0)) return null;
  return conf2Typo(ctx, start, end, "waste", undefined, n1);
}

// en.yaml rule en.contextualConfusions def conf2Relay
export function conf2Relay(
  ctx: DetectContext,
  word: string,
  start: number,
  end: number,
  h: EnWordsAround,
): RawFinding | null {
  const n0 = h.N[0];
  const n1 = h.N[1];
  if (!(n0?.w === "on" && n1 && n1.w !== "behalf")) return null;
  const p = h.P[0];
  const ok = p
    ? CONF2_RELAY_LEAD.has(p.w) ||
      (/ly$/.test(p.w) && !!englishWordInfo(p.w)?.adverb) ||
      (!!englishWordInfo(p.w)?.plural && !CONF2_DET.has(h.P[1]?.w ?? ""))
    : enClauseOpensAt(ctx.text, start) && CONF2_OBJECTS.has(n1.w);
  if (!ok) return null;
  return conf2Typo(ctx, start, end, "rely", p, n0);
}

// en.yaml rule en.contextualConfusions def conf2Off
export function conf2Off(
  ctx: DetectContext,
  word: string,
  start: number,
  end: number,
  h: EnWordsAround,
): RawFinding | null {
  const p0 = h.P[0];
  const n0 = h.N[0];
  if (!(p0 && CONF2_THINK_KNOW.has(p0.w) && n0 && !/^(?:and|of|hand|handedly)$/.test(n0.w)))
    return null;
  const n1 = h.N[1];
  if (n0.w === "the" && CONF2_OFF_IDIOMS.has(n1?.w ?? "")) return null;
  return conf2Typo(ctx, start, end, "of", p0, n0);
}

// en.yaml rule en.contextualConfusions def conf2Tuff
export function conf2Tuff(
  ctx: DetectContext,
  word: string,
  start: number,
  end: number,
  h: EnWordsAround,
): RawFinding | null {
  if (!(h.N[0]?.w === "like")) return null;
  const p = h.P[0]?.w;
  if (
    p &&
    !CONF2_DET.has(p) &&
    !CONF2_BE.has(p) &&
    !CONF2_INTENSIFIERS.has(p) &&
    !conf2LemmaIn(p, CONF2_LINKING_LEMMAS)
  )
    return null;
  return conf2Typo(ctx, start, end, "tough", undefined, h.N[0]);
}

// en.yaml rule en.contextualConfusions def conf2Yea
export function conf2Yea(
  ctx: DetectContext,
  word: string,
  start: number,
  end: number,
  _h: EnWordsAround,
): RawFinding | null {
  const after =
    /^(?:[ \t\u00a0]*,|[ \t\u00a0]+[-–—]+|[-–—]+(?=[ \t\u00a0]))[ \t\u00a0]*([A-Za-z]*)/.exec(
      ctx.text.slice(end, end + 24),
    );
  if (!(after && !/^(?:though|verily|nay)$/i.test(after[1]))) return null;
  if (/\b(?:nay|yeas|nays)\b/i.test(ctx.text.slice(Math.max(0, start - 64), end + 64))) return null;
  return conf2Typo(ctx, start, end, "yeah", undefined, undefined);
}

// en.yaml rule en.contextualConfusions def conf2Price
export function conf2Price(
  ctx: DetectContext,
  word: string,
  start: number,
  end: number,
  h: EnWordsAround,
): RawFinding | null {
  const i = CONF2_PRIZE_LEAD.has(h.P[0]?.w ?? "") ? 1 : 0;
  if (!CONF2_WIN.has(h.P[i]?.w ?? "")) return null;
  const n0 = h.N[0];
  if (
    n0 &&
    !CONF2_CLOSED.has(n0.w) &&
    !CONF2_TIME.has(n0.w) &&
    !n0.w.includes("'") &&
    conf2PriceNoun(n0.w)
  )
    return null;
  return conf2Typo(ctx, start, end, /s$/.test(word) ? "prizes" : "prize", h.P[i], undefined);
}

// en.yaml rule en.contextualConfusions def conf2PriceNoun
export function conf2PriceNoun(w: string) {
  const entry = englishWordInfo(w);
  return entry ? (entry.noun || entry.plural) && !hasVerbForm(w, "past") : conf2Nounish(w);
}

// en.yaml rule en.contextualConfusions def conf2Loose
export function conf2Loose(
  ctx: DetectContext,
  word: string,
  start: number,
  end: number,
  h: EnWordsAround,
): RawFinding | null {
  const p0 = h.P[0];
  const p1 = h.P[1];
  if (!(
    p0?.w === "to" &&
    !h.P.some((p) => p.w === "from") &&
    !CONF2_SETTING_VERBS.has(p1?.w ?? "")
  ))
    return null;
  const n0 = h.N[0];
  if (!(n0 ? CONF2_LOSE_OBJECT.has(n0.w) : enClauseClosesAt(ctx.text, end))) return null;
  return conf2Typo(ctx, start, end, "lose", p0, n0);
}

// en.yaml rule en.contextualConfusions def conf2Lose
export function conf2Lose(
  ctx: DetectContext,
  word: string,
  start: number,
  end: number,
  h: EnWordsAround,
): RawFinding | null {
  if (!(h.P[0]?.w === "too")) return null;
  const n0 = h.N[0];
  if (!(
    /^[ \t\u00a0]+(?:and|or|but|for|with|in|on|at)(?![A-Za-z])/i.test(
      ctx.text.slice(end, end + 12),
    ) ||
    (!n0 && enClauseClosesAt(ctx.text, end))
  ))
    return null;
  return conf2Typo(ctx, start, end, "loose", h.P[0], n0);
}

// en.yaml rule en.contextualConfusions def conf2They
export function conf2They(
  ctx: DetectContext,
  word: string,
  start: number,
  end: number,
  h: EnWordsAround,
): RawFinding | null {
  const p0 = h.P[0];
  if (!p0) return null;
  const p1 = h.P[1];
  const n0 = h.N[0];
  if (n0 && (CONF2_FINITE.has(n0.w) || conf2PureFinite(n0.w))) return null;
  if (!(
    (CONF2_THEM_PREPOSITIONS.has(p0.w) && !(p0.w === "about" && CONF2_WH.has(p1?.w ?? ""))) ||
    (hasVerbForm(p0.w, "base") &&
      !CONF2_AUX.has(p0.w) &&
      !conf2LemmaIn(p0.w, CONF2_BARE_CLAUSE) &&
      !!n0 &&
      CONF2_THEM_NEXT.has(n0.w) &&
      (enClauseOpensAt(ctx.text, p0.start) || CONF2_THEM_LEAD.has(p1?.w ?? "")))
  ))
    return null;
  return conf2Emit(
    ctx,
    start,
    end,
    "englishPronounCase",
    "review_msg_pronoun_object_case",
    ["them"],
    [p0.start, n0?.end ?? end],
  );
}

// en.yaml rule en.contextualConfusions def conf2There
export function conf2There(
  ctx: DetectContext,
  word: string,
  start: number,
  end: number,
  h: EnWordsAround,
): RawFinding | null {
  const p0 = h.P[0];
  const p1 = h.P[1];
  const n0 = h.N[0];
  if (!n0) return null;
  const n1 = h.N[1];
  return p0 &&
    CONF2_CUES.has(p0.w) &&
    n1 &&
    hasVerbForm(n0.w, "ing") &&
    !/^(?:being|going)$/.test(n0.w)
    ? conf2TheirFamily(ctx, start, end, h, "review_msg_they_are", "they're", p0)
    : conf2TheirThere(ctx, start, h, p0, p1)
      ? conf2TheirFamily(ctx, start, end, h, "review_msg_their_possessive", "their", p0)
      : null;
}

// en.yaml rule en.contextualConfusions def conf2TheirThere
export function conf2TheirThere(
  ctx: DetectContext,
  start: number,
  h: EnWordsAround,
  p0: EnClauseWord | undefined,
  p1: EnClauseWord | undefined,
) {
  const head = /^(?:and|or)$/.test(p0?.w ?? "") ? conf2NounPhrase(h.N, 0, true) : -1;
  return (
    (!enClauseOpensAt(ctx.text, start) &&
      conf2ObjectVerb(ctx.text, p0, p1, CONF2_THERE_BLOCK) &&
      conf2NounPhrase(h.N, 0, true) >= 0 &&
      conf2GerundHeadOk(ctx, h, p0)) ||
    (head >= 0 && enClauseClosesAt(ctx.text, h.N[head].end)) ||
    conf2PrepositionObject(ctx, h) ||
    (conf2ClauseStart(ctx, start, h) && conf2SubjectPhrase(h.N, true))
  );
}

// en.yaml rule en.contextualConfusions def conf2Their
export function conf2Their(
  ctx: DetectContext,
  word: string,
  start: number,
  end: number,
  h: EnWordsAround,
): RawFinding | null {
  const n0 = h.N[0];
  if (!(n0 ? CONF2_PLACE_NEXT.has(n0.w) : enClauseClosesAt(ctx.text, end))) return null;
  const j = conf2PlaceVerb(h.P, 1);
  if (!(j > 0)) return null;
  return conf2TheirFamily(ctx, start, end, h, "review_msg_their_there", "there", h.P[j]);
}

// en.yaml rule en.contextualConfusions def conf2PlaceVerb
export function conf2PlaceVerb(p: readonly EnClauseWord[], j: number): number {
  return j > 3 || !p[j] || !p[j - 1]
    ? -1
    : conf2LemmaIn(p[j].w, CONF2_PLACE_VERBS) &&
        (CONF2_DET.has(p[j - 1].w) || /^(?:it|them)$/.test(p[j - 1].w))
      ? j
      : conf2PlaceVerb(p, j + 1);
}

// en.yaml rule en.contextualConfusions def conf2Theyre
export function conf2Theyre(
  ctx: DetectContext,
  word: string,
  start: number,
  end: number,
  h: EnWordsAround,
): RawFinding | null {
  const p0 = h.P[0];
  const p1 = h.P[1];
  if (
    p0?.w === "while" ||
    (p0?.w === "like" && !!p1 && !CONF2_SUBJECTS.has(p1.w) && !!englishWordInfo(p1.w)?.verbs.length)
  )
    return null;
  const p2 = h.P[2];
  const phrase = conf2NounPhrase(h.N, 0, true) >= 0;
  const ok =
    (phrase && !!p0 && /^(?:are|were|is|was)$/.test(p0.w) && CONF2_WH.has(p1?.w ?? "")) ||
    (phrase &&
      conf2ObjectVerb(ctx.text, p0, p1, CONF2_CLAUSE_LEMMAS) &&
      conf2GerundHeadOk(ctx, h, p0)) ||
    (phrase &&
      !!p0 &&
      CONF2_OBJECTS.has(p0.w) &&
      conf2ObjectVerb(ctx.text, p1, p2, CONF2_CLAUSE_LEMMAS) &&
      conf2GerundHeadOk(ctx, h, p1)) ||
    (conf2ClauseStart(ctx, start, h) && conf2SubjectPhrase(h.N, true));
  if (!ok) return null;
  return conf2TheirFamily(ctx, start, end, h, "review_msg_their_possessive", "their", p0);
}

// en.yaml rule en.contextualConfusions def conf2To
export function conf2To(
  ctx: DetectContext,
  word: string,
  start: number,
  end: number,
  h: EnWordsAround,
): RawFinding | null {
  const listed =
    /,[ \t\u00a0]{0,8}$/.test(ctx.text.slice(Math.max(0, start - 9), start)) &&
    /^[ \t\u00a0]{0,8}[.!?](?![\p{L}\p{N}])|^[ \t\u00a0]*$/u.test(ctx.text.slice(end, end + 10));
  if (!(
    listed ||
    (/^(?:loud|loudly)$/.test(h.N[0]?.w ?? "") &&
      h.N.length === 1 &&
      conf2LemmaIn(h.P[0]?.w ?? "", CONF2_SPEECH_LEMMAS) &&
      enClauseClosesAt(ctx.text, h.N[0].end))
  ))
    return null;
  return conf2Emit(
    ctx,
    start,
    end,
    "englishToToo",
    "review_msg_to_too",
    ["too"],
    [h.P[0]?.start ?? start, h.N[0]?.end ?? end],
  );
}

// en.yaml rule en.contextualConfusions def conf2Where
export function conf2Where(
  ctx: DetectContext,
  word: string,
  start: number,
  end: number,
  h: EnWordsAround,
): RawFinding | null {
  const n0 = h.N[0];
  if (!(enClauseOpensAt(ctx.text, start) && n0 && /^(?:you|we|they)$/.test(n0.w))) return null;
  const n1 = h.N[1];
  if (!(n1 && CONF2_WERE_PREDICATES.has(n1.w))) return null;
  return conf2Emit(
    ctx,
    start,
    end,
    "englishWereWhere",
    "review_msg_were_where",
    ["were"],
    [start, n1.end],
  );
}

